import os, json, numpy as np

N = 26
SCI_BOUND = 'storage/Scientia/nmap/n26/exports_for_noesis_ii/scientia_sota_528_boundary_equalities_tol_2e8.json'
OUT_JSON  = 'storage/noesis/nmap/scientia_23_boundary_jaccard_2e8_v2.json'

SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'

def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
    else:
        centers = []
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, float)
        r = np.full(N, 0.08, float)
    return c, r

def boundary_from_pack(c, r, tol):
    x=c[:,0]; y=c[:,1]
    S=set()
    for i in range(N):
        if x[i]-r[i] <= tol: S.add((i,'xL'))
        if 1.0-x[i]-r[i] <= tol: S.add((i,'xR'))
        if y[i]-r[i] <= tol: S.add((i,'yB'))
        if 1.0-y[i]-r[i] <= tol: S.add((i,'yT'))
    return S

def load_scientia_boundary(path):
    S=set()
    if not os.path.exists(path): return S, False
    try:
        data = json.load(open(path,'r'))
        arr = data.get('boundary_equalities', [])
        for ent in arr:
            i = int(ent.get('disc'))
            side = str(ent.get('side'))
            if 0 <= i < N and side in ('xL','xR','yB','yT'):
                S.add((i, side))
        return S, True
    except Exception:
        return set(), False

def construct_packing():
    c, r = load_snapshot()
    sci_set, ok = load_scientia_boundary(SCI_BOUND)
    noe_set = boundary_from_pack(c, r, tol=2e-8)

    inter = len(sci_set & noe_set)
    uni   = len(sci_set | noe_set) if (sci_set or noe_set) else 0
    j = (inter/uni) if uni>0 else 1.0

    report = {
        'scientia_boundary_path': SCI_BOUND,
        'scientia_loaded': ok,
        'scientia_count': len(sci_set),
        'noesis_count': len(noe_set),
        'intersection': inter,
        'union': uni,
        'jaccard': j,
        'missing_in_scientia': sorted(list(noe_set - sci_set)),
        'missing_in_noesis': sorted(list(sci_set - noe_set)),
        'tolerance': '2e-8'
    }
    try:
        os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
        with open(OUT_JSON,'w') as f: json.dump(report, f, indent=2)
        print('SCI_BOUNDARY_2E8_V2_JSON:', OUT_JSON)
        print('COUNTS sci/noe/inter/uni:', report['scientia_count'], report['noesis_count'], inter, uni)
        print('JACCARD_2E8_V2:', j)
    except Exception as e:
        print('LOG_WRITE_ERROR:', e)

    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
